          "subtitle": "流转有度",
          "rarity": "R",
          "definition": "由资本技术构成决定并反映技术构成变化的资本价值构成，称为资本有机构成。",
          "keyPoints": [
            "技术构成考察生产资料与劳动力的比例。",
            "价值构成考察不变资本与可变资本的比例，但并非所有价格变化都反映技术变化。"
          ],
          "example": "教学例：每名工人操作更多先进设备，若这一技术变化反映为c/v提高，就体现资本有机构成的提高。",
          "misconception": "原料价格单独上涨造成c/v变化，不能直接认定技术构成已经提高。",
