          "title": "公司法人治理结构",
          "chapterId": "ch12",
          "courseId": "political-economy",
          "subtitle": "织理成章",
          "rarity": "R",
          "definition": "公司法人治理结构通过出资者、决策者、经营者与监督者之间的权利责任安排，实现相互协调和制衡。",
          "keyPoints": [
            "所有权与经营权分离后，需要明确授权和监督。",
            "治理解决权责与制衡，日常管理着重具体经营执行，两者相联系。"
          ],
          "example": "教学例：重大事项按授权由相应机构决策，经营层执行并接受监督，不能由一人随意越过全部程序。",
          "misconception": "法人治理不等于“法人代表个人治理”，也不意味着各主体职责完全一样。",
