          "title": "农业产业化与社会化服务",
          "chapterId": "ch12",
          "courseId": "political-economy",
          "subtitle": "循理观源",
          "rarity": "SSR",
          "definition": "农业产业化以利益机制连接产前、产中、产后，社会化服务则向农业提供技术、信息、农机等专业支持。",
          "keyPoints": [
            "把分散农户与市场、加工和销售相联结。",
            "组织协作应重视农民利益，服务规模化不要求土地所有权都归一家企业。"
          ],
          "example": "教学例：农户保留家庭经营，合作组织提供农机、储运和销售服务，可以提高与市场衔接的能力。",
          "misconception": "产业化不只是把农田建成工厂，也不能把社会化服务等同于取消农户经营。",
