          "chapterId": "ch13",
          "courseId": "political-economy",
          "subtitle": "经纬有章",
          "rarity": "R",
          "definition": "初次分配是在生产活动及相关经济关系基础上，形成劳动报酬、生产税净额、营业盈余等原始收入的过程。",
          "keyPoints": [
            "政府、企业和居民都可能参与初次分配。",
            "须区分参与生产及财产关系形成的收入与后续经常转移。"
          ],
          "example": "教学例：企业支付劳动报酬、形成营业盈余等属于初次分配；此后个人缴纳所得税属于再分配。",
