          "id": "pe_150",
          "title": "按劳分配为主体",
          "chapterId": "ch13",
          "courseId": "political-economy",
          "subtitle": "观时察势",
          "rarity": "R",
          "definition": "按劳分配为主体、多种分配方式并存的制度，与公有制为主体、多种所有制经济共同发展的结构相联系。",
          "keyPoints": [
            "主体地位与多种方式并存不能割裂。",
            "既调动劳动者积极性，也依法规范不同要素参与分配。"
          ],
          "example": "教学例：分析分配制度时，把公有制领域的按劳分配与其他所有制和要素收入一起考察。",
          "misconception": "多种方式并存不是否定按劳分配主体；主体地位也不表示所有收入都只能用同一个尺度计算。",
