          "courseId": "political-economy",
          "subtitle": "织理成章",
          "rarity": "SSR",
          "definition": "社会保险以制度化参保和风险共担提供保障；社会救助针对难以维持最低生活水平者给予无偿帮助。",
          "keyPoints": [
            "两者对象、筹资和待遇条件有所不同。",
            "二者互为衔接，不能用商业保险替代全部基本保障职责。"
          ],
          "example": "教学例：按制度领取失业保险待遇与困难家庭获得救助，虽然都缓解困难，但适用条件和保障机制不同。",
          "misconception": "救助不等于保险缴费回报，保险也不等于只有陷入最低生活困难才能获得待遇。",
