          "example": "教学例：改善公共基础设施和维护公平交易规则，与直接替每家企业决定所有经营事项属于不同做法。",
          "misconception": "政府有经济职能，不等于政府必须包办一切；发挥市场作用，也不等于政府完全不作为。",
