          "chapterId": "ch15",
          "courseId": "political-economy",
          "subtitle": "研真启卷",
          "rarity": "SSR",
          "definition": "货币政策通过货币、信贷和利率等机制影响经济运行，服务于相应宏观调控目标。",
          "keyPoints": [
            "中央银行工具通过金融体系传导，其效果受需求和预期等条件影响。",
            "货币政策与财政政策可以协调，但职责和工具不同。"
          ],
          "example": "教学例：融资成本下降可能支持投资，但若企业缺乏有效需求，投资不一定按固定比例增加。",
          "misconception": "增加货币供给不等于直接增加真实资源，利率变化也不保证所有企业立即作同样反应。",
