          "chapterId": "ch15",
          "courseId": "political-economy",
          "subtitle": "循理观源",
          "rarity": "C",
          "definition": "宏观调控综合运用规划、产业、财政、货币、收入及相关法律和行政手段，重视工具之间的协调。",
          "keyPoints": [
            "不同工具对总量、结构及预期的影响不完全相同。",
            "政策组合须围绕目标安排，避免措施相互抵消或忽视副作用。"
          ],
          "example": "教学例：支持产业升级时，可协调研发支持、技能培训与融资条件，而不只依赖一个总量指标。",
