          "chapterId": "ch15",
          "courseId": "political-economy",
          "subtitle": "经纬有章",
          "rarity": "SR",
          "definition": "市场监管体系把依法行政执法、行业自律、舆论监督和群众参与等结合起来，维护市场秩序。",
          "keyPoints": [
            "监管服务于公平竞争和经营者、消费者的合法权益。",
            "多方参与不能替代法定职责，各类监督须遵循相应规则。"
          ],
          "example": "教学例：消费者反映问题、行业纠正不当行为与监管部门依法调查，可以形成相互配合的监督。",
