          "chapterId": "ch15",
          "courseId": "political-economy",
          "subtitle": "同流共济",
          "rarity": "R",
          "definition": "经济性监管主要针对市场进入、竞争和垄断等经济行为，防止损害公平竞争与资源配置。",
          "keyPoints": [
            "自然垄断与其他垄断情形需结合条件区分。",
            "防止不正当竞争不等于阻止一切正常竞争或效率提升。"
          ],
          "example": "教学例：对排斥竞争的交易安排进行审查，应看实际市场行为和影响，而不只是企业规模。",
