          "chapterId": "ch15",
          "courseId": "political-economy",
          "subtitle": "明辨知微",
          "rarity": "SSR",
          "definition": "社会性监管针对市场活动对健康、安全、环境等社会利益的影响，保护劳动者和消费者等主体。",
          "keyPoints": [
            "可通过规则、检查、标准及社会监督等方式实施。",
            "公共安全和生态后果不能只由企业短期利润衡量。"
          ],
