          "id": "pe_174",
          "title": "经济全球化",
          "chapterId": "ch16",
          "courseId": "political-economy",
          "subtitle": "温故见新",
          "rarity": "UR",
          "definition": "经济全球化是以国际分工为基础，生产要素跨国流动和配置不断加强、各国经济联系日益紧密的过程。",
          "keyPoints": [
            "贸易、生产和金融等联系互相推动。",
            "全球化不意味着各国条件、利益和发展水平完全相同。"
          ],
          "example": "教学例：一件产品由多国提供技术、部件和资金，再销往不同市场，体现跨国经济联系。",
          "misconception": "全球化不是国界和国家利益已经消失，也不等于各国在所有领域获得相同收益。",
