          "title": "生产全球化",
          "chapterId": "ch16",
          "courseId": "political-economy",
          "subtitle": "观时察势",
          "rarity": "SR",
          "definition": "生产全球化是企业生产过程跨越国界，通过国际分工协作配置生产要素的趋势。",
          "keyPoints": [
            "产品的不同环节可以分布于多个国家。",
            "跨国协作提高分工效率，也使供应链相互依赖增强。"
          ],
          "example": "教学例：一件设备的设计、零件制造和组装分别在不同国家完成，属于生产环节的跨国协作。",
