          "subtitle": "循源问道",
          "rarity": "SSR",
          "definition": "经济全球化带来市场、资金和技术机遇，也可能增加外部冲击、竞争压力与发展不平衡，影响具有双重性。",
          "keyPoints": [
            "不同国家所处位置、能力和规则条件不同，获益与风险不会完全相同。",
            "应提高自身能力并参与合作，而非把全球化简单判为全利或全害。"
          ],
          "example": "教学例：企业进入更大市场获得订单，同时面对国际竞争与外需波动，需兼顾能力和风险。",
