          "courseId": "xi-jinping-economic-thought",
          "chapterId": "ch4",
          "title": "两个毫不动摇",
          "subtitle": "双翼同振",
          "rarity": "SSR",
          "definition": "两个毫不动摇指巩固和发展公有制经济，鼓励、支持、引导非公有制经济发展；二者相辅相成，共同构成社会主义市场经济的重要组成部分。",
          "keyPoints": [
            "毫不动摇巩固和发展公有制经济。",
            "毫不动摇鼓励、支持、引导非公有制经济发展。",
            "两者都是社会主义市场经济的重要组成部分，依法平等使用要素、公平竞争并受到法律保护。"
          ],
          "example": "教学例：一地既推进国有企业改革，也依法改善民营企业准入和融资环境，体现两个方面可以同时推进。",
          "misconception": "“两个毫不动摇”是“毫不动摇巩固和发展公有制经济，毫不动摇鼓励、支持、引导非公有制经济发展”，二者有机统一、不是对立的。",
